                    frappe.form_dict['key'] = old_share_key
                else:
                    frappe.form_dict.pop('key', None)
                if share_key_created:
                    share_key.delete(ignore_permissions=True)
                    frappe.db.commit()
            frappe.response['filename'] = request.name + '.pdf'
