    def item_suggestions(data):
        user = actor()
        company = data.get('company')
        department = data.get('department')
        require_active_scope(user, company, department)
        if not read_capabilities(user)['create']:
            fail('error.permission')
        query = checked_text(data.get('query'), 100)
        if len(query) < 2:
            return []
        pattern = '%' + query + '%'
        is_super = super_user(user)
        shared = is_super or any(role in roles_of(user) for role in ['PA Manager', 'PA Purchasing', 'PA Approver', 'PA Receiver', 'PA Company Admin'])
        visibility = '' if is_super else " and (p.requester=%s or p.status!='Draft')" if shared else ' and p.requester=%s'
        params = [company, department, pattern, pattern]
        if not is_super:
            params.append(user)
        history = frappe.db.sql(
            "select i.item_code, i.item_name, i.description, i.uom, p.name as request_name, "
            "p.company, p.department, p.requester, p.status "
            "from `tabPA Purchase Request Item` i "
            "join `tabPA Purchase Request` p on p.name=i.parent "
            "where p.company=%s and p.department=%s "
            "and (i.item_name like %s or i.item_code like %s)" + visibility +
            ' order by p.modified desc, i.idx asc limit 500', tuple(params), as_dict=True)
        suggestions = []
        seen = set()
        visible_requests = {}
        for row in history:
            if row.request_name not in visible_requests:
                visible_requests[row.request_name] = can_read(user, row)
            if not visible_requests[row.request_name]:
                continue
            key = ((row.item_code or '').strip().casefold(), (row.item_name or '').strip().casefold())
            if not key[1] or key in seen:
                continue
            seen.add(key)
            suggestions.append({'name': '', 'product_code': row.item_code or '', 'product_name': row.item_name,
                                'description': row.description or '', 'uom': row.uom or '', 'source': 'history'})
            if len(suggestions) == 20:
                return suggestions
        products = frappe.db.sql(
            'select name, product_code, product_name from `tabProduct` '
            'where is_active=1 and (product_name like %s or product_code like %s) '
            'order by product_name limit 20', (pattern, pattern), as_dict=True)
        for row in products:
            key = ((row.product_code or '').strip().casefold(), (row.product_name or '').strip().casefold())
            if key in seen:
                continue
            seen.add(key)
            suggestions.append({'name': row.name, 'product_code': row.product_code or '',
                                'product_name': row.product_name, 'source': 'product'})
            if len(suggestions) == 20:
                break
        return suggestions


    def validate_workflow(doc):
        user = actor()
        require_role(user, 'PA Company Admin')
        require_scope(user, doc.company, doc.department)
        old = doc.get_doc_before_save()
        if old:
            require_scope(user, old.company, old.department)
        start = scaled(doc.amount_from)
        end = scaled(doc.amount_to)
        if doc.currency != 'VND' or (doc.has_amount_to and end <= start) or not doc.steps or len(doc.steps) > 30:
            fail('error.range')
        seen = []
        for step in doc.steps:
            if int(step.step_order or 0) < 1 or step.step_order in seen or step.approval_method not in ['Any', 'All'] or step.approver_source not in ['User', 'Role', 'Department Manager']:
                fail('error.range')
            seen.append(step.step_order)
            step.step_name = checked_text(step.step_name, 140, True)
            if step.approver_source == 'User' and not frappe.db.get_value('User', step.approver_user, 'enabled'):
                fail('error.no_approver')
            if step.approver_source == 'Role' and not frappe.db.exists('Role', step.approver_role):
                fail('error.no_approver')


