        def info(key, value):
            return '<td style="padding:8px 12px;border-bottom:1px solid #e5eaf0;vertical-align:top;width:50%"><div style="font-size:12px;color:#64748b">' + clean(t(key)) + '</div><div style="font-size:14px;color:#172033;font-weight:600">' + clean(value) + '</div></td>'
