            for field in frappe.get_meta('Company').fields:
                if 'image' in (field.fieldname or '').lower() or 'image' in (field.label or '').lower():
                    logo_field = field.fieldname
                    break
        logo_url = frappe.db.get_value('Company', request.company, logo_field) if logo_field else None
        if not logo_url:
            logo_url = frappe.db.get_single_value('Website Settings', 'app_logo')
        inline_images = []
        logo_html = ''
        if logo_url:
            file_name = frappe.db.get_value('File', {'file_url': logo_url}, 'file_name')
            file_doc_name = frappe.db.get_value('File', {'file_url': logo_url}, 'name')
            logo_source = frappe.utils.get_url(logo_url)
            try:
                if file_doc_name:
                    logo_file = frappe.get_doc('File', file_doc_name)
                    logo_bytes = logo_file.get_content()
                    if logo_bytes:
                        file_name = file_name or logo_url.rsplit('/', 1)[-1]
                        inline_images.append({'filename': file_name, 'filecontent': logo_bytes})
                        logo_source = file_name
                        logo_html = '<img embed="' + escape(logo_source) + '" alt="" width="145" style="display:block;max-width:145px;max-height:52px;object-fit:contain">'
            except Exception:
                inline_images = []
