            '<tr><td style="padding:9px 7px;text-align:right;color:#315d83;border-top:1px solid #dce4ed">', clean(t('field.final_total') if priced else t('field.estimated_total')), '</td><td style="padding:9px 7px;text-align:right;border-top:1px solid #dce4ed"><strong style="font-size:16px">', money(request.final_total if priced else request.estimated_total), '</strong></td></tr></table>',
            '<div style="padding:12px 0 18px">', ('' if action_url else '<a href="' + escape(approve_url) + '" style="display:inline-block;background:#1769aa;color:#fff;text-decoration:none;font-weight:700;font-size:14px;padding:12px 20px;border-radius:6px">' + clean(t('notification.approve_button')) + '</a> '), '<a href="', escape(detail_url), '" style="display:inline-block;color:#1769aa;font-size:14px;padding:12px 10px">', clean(t('notification.view_button')), '</a></div>',
            '<p style="font-size:12px;line-height:1.6;color:#64748b;margin:0">', clean(t('notification.attachment_note')), ' ', clean(t('notification.outlook_confirm_note') if action_url else t('notification.confirm_note')), '</p>',
            '</td></tr></table></div>'
        ]) + '</body></html>'
