    def notification_worker():
        if not frappe.db.get_single_value('PA Settings', 'email_enabled'):
            return
        pdf_cache = {}
        for row in frappe.get_all('PA Notification Outbox', filters={'status': 'Pending', 'attempts': ['<', 5]}, fields=['name'], limit_page_length=100):
            query_lock('select name from `tabPA Notification Outbox` where name=%s for update', (row.name,))
            outbox = locked_doc('PA Notification Outbox', row.name)
            if outbox.status != 'Pending':
                continue
            instance = frappe.get_doc(INST, outbox.instance)
            request = frappe.get_doc(PR, outbox.request)
            active = request.status == 'Pending Approval' and instance.status == 'Pending' and request.current_instance == instance.name and instance.current_sequence == outbox.step_order and eligible(outbox.recipient, request) and any(a.user == outbox.recipient and a.step_order == outbox.step_order and a.status == 'Pending' for a in instance.assignees)
            if not active:
                outbox.status = 'Cancelled'
            else:
                outbox.attempts = int(outbox.attempts or 0) + 1
                try:
                    cache_key = request.name + ':' + str(request.revision)
                    if cache_key not in pdf_cache:
                        pdf_cache[cache_key] = frappe.get_print(PR, request.name, print_format='PA Purchase Request Invoice', as_pdf=True, pdf_generator='chrome')
                    mail_state = frappe.call('purchase_approval_navigation.graph_mail.status')
                    action_url = frappe.call('purchase_approval_navigation.outlook_action.issue_action', outbox_name=outbox.name) if mail_state.get('enabled') else None
                    message, inline_images = approval_email_message(request, outbox, action_url)
                    if mail_state.get('enabled'):
                        frappe.call('purchase_approval_navigation.graph_mail.send_approval', recipient=frappe.db.get_value('User', outbox.recipient, 'email') or outbox.recipient,
                                    subject=outbox.subject, message=message, pdf_name=request.name + '.pdf',
                                    pdf_bytes=pdf_cache[cache_key], inline_images=inline_images)
                    else:
                        frappe.sendmail(recipients=[outbox.recipient], subject=outbox.subject, message=message, attachments=[{'fname': request.name + '.pdf', 'fcontent': pdf_cache[cache_key]}], inline_images=inline_images)
                    outbox.status = 'Sent'
                    outbox.sent_at = frappe.utils.now()
                    outbox.last_error = None
                except Exception:
                    outbox.last_error = t('error.email')
            outbox.save(ignore_permissions=True)
    
    
