        if command == 'get_purchase_request_pdf':
            request = lock_request(data.get('name'), {}, False)
            share_key = frappe.get_doc({'doctype': 'Document Share Key', 'reference_doctype': PR, 'reference_docname': request.name, 'expires_on': frappe.utils.nowdate()})
            had_share_key = 'key' in frappe.form_dict
            old_share_key = frappe.form_dict.get('key')
            share_key_created = False
            try:
                share_key.insert(ignore_permissions=True)
                share_key_created = True
                temporary_key = share_key.key
                # Print permission validates share keys through get_cached_value, which can read from a replica.
                # Commit this read-only request's temporary key before the print permission check.
                frappe.db.commit()
                frappe.form_dict['key'] = temporary_key
                pdf = frappe.get_print(PR, request.name, print_format='PA Purchase Request Invoice', as_pdf=True, pdf_generator='chrome')
            finally:
                if had_share_key:
                    frappe.form_dict['key'] = old_share_key
                else:
                    frappe.form_dict.pop('key', None)
                if share_key_created:
                    share_key.delete(ignore_permissions=True)
                    frappe.db.commit()
            frappe.response['filename'] = request.name + '.pdf'
            frappe.response['filecontent'] = pdf
            frappe.response['type'] = 'pdf'
            return None
        if command == 'list_purchase_requests':
