    def read_capabilities(user):
        return {
            'create': has_role(user, 'PA Requester'),
            'approvals': any(has_role(user, role) for role in ['PA Approver', 'PA Manager', 'PA Company Admin']),
            'purchasing': has_role(user, 'PA Purchasing'),
            'receiving': has_role(user, 'PA Receiver'),
            'administration': has_role(user, 'PA Company Admin'),
        }


    def org_admin(user):
        if not (super_user(user) or 'PA Company Admin' in roles_of(user) or 'System Manager' in roles_of(user)):
            fail('error.permission')


    def org_company_scope(user, company):
        org_admin(user)
        if not company or not frappe.db.exists('Company', company):
            fail('error.org_not_found')
        if not super_user(user) and 'System Manager' not in roles_of(user):
            allowed = [row.for_value for row in frappe.get_all('User Permission', filters={'user': user, 'allow': 'Company'}, fields=['for_value'])]
            if company not in allowed:
                fail('error.permission')


    def org_kind(data):
        kind = data.get('kind')
        if kind not in ['company', 'department']:
            fail('error.filters')
        return 'Company' if kind == 'company' else 'Department'


    def org_values(doc):
        fields = ['company_code', 'short_name', 'company_name', 'tax_code', 'phone', 'email', 'address', 'active'] if doc.doctype == 'Company' else ['department_code', 'department_name', 'company', 'active']
        return {'name': doc.name, 'modified': str(doc.modified), **{key: doc.get(key) for key in fields}}


    def org_list(data):
        user = actor()
        org_admin(user)
        company_filter = data.get('company')
        if company_filter:
            org_company_scope(user, company_filter)
        companies = []
        for row in frappe.get_all('Company', fields=['name'], order_by='company_name', limit_page_length=0):
            try:
                org_company_scope(user, row.name)
            except Exception:
                continue
            if not company_filter or row.name == company_filter:
                companies.append(org_values(frappe.get_doc('Company', row.name)))
        departments = []
        for company in companies:
            for row in frappe.get_all('Department', filters={'company': company['name']}, fields=['name'], order_by='department_name', limit_page_length=0):
                departments.append(org_values(frappe.get_doc('Department', row.name)))
        return {'companies': companies, 'departments': departments, 'can_create_company': super_user(user)}


    def org_get(data):
        doctype = org_kind(data)
        name = checked_text(data.get('name'), 140, True)
        row = frappe.db.get_value(doctype, name, 'name' if doctype == 'Company' else 'company')
        if not row:
            fail('error.org_not_found')
        org_company_scope(actor(), name if doctype == 'Company' else row)
        return org_values(frappe.get_doc(doctype, name))


    def org_has_references(department):
        return any(frappe.db.exists(doctype, {'department': department}) for doctype in [PR, WF, INST, HIST])


    def org_flag(value):
        if value not in [0, 1, '0', '1', False, True]:
            fail('error.filters')
        return int(value)


    def org_rename(doctype, old_name, new_code):
        if old_name == new_code:
            return old_name
        if frappe.db.exists(doctype, new_code):
            fail('error.org_duplicate')
        new_name = frappe.rename_doc(doctype, old_name, new_code, ignore_permissions=True, show_alert=False, rebuild_search=False)
        # User Permission.for_value is Data, so Frappe's Link-field rename cannot update it.
        for permission in frappe.get_all('User Permission', filters={'allow': doctype, 'for_value': old_name}, fields=['name']):
            frappe.db.set_value('User Permission', permission.name, 'for_value', new_name)
        return new_name


    def validate_org_doc(doc):
        user = actor()
        org_admin(user)
        old = doc.get_doc_before_save()
        doc.active = org_flag(doc.active)
        if doc.doctype == 'Company':
            code = checked_text(doc.company_code, 50, True)
            doc.company_code = code
            doc.company_name = checked_text(doc.company_name, 140, True)
            for item in [('short_name', 140), ('tax_code', 140), ('phone', 50), ('email', 140), ('address', 2000)]:
                doc.set(item[0], checked_text(doc.get(item[0]), item[1]))
            if old:
                org_company_scope(user, old.name)
                if code != old.company_code or doc.name != old.name:
                    fail('error.org_code_locked')
            elif not super_user(user):
                fail('error.permission')
            elif frappe.db.exists('Company', code):
                fail('error.org_duplicate')
        elif doc.doctype == 'Department':
            code = checked_text(doc.department_code, 50, True)
            doc.department_code = code
            doc.department_name = checked_text(doc.department_name, 140, True)
            org_company_scope(user, doc.company)
            if old:
                org_company_scope(user, old.company)
                if code != old.department_code or doc.name != old.name:
                    fail('error.org_code_locked')
                if old.company != doc.company and org_has_references(old.name):
                    fail('error.org_department_linked')
            elif frappe.db.exists('Department', code):
                fail('error.org_duplicate')
            if doc.active and not frappe.db.get_value('Company', doc.company, 'active'):
                fail('error.org_company_inactive')
        else:
            fail('error.filters')


    def org_save(data):
        user = actor()
        doctype = org_kind(data)
        org_admin(user)
        name = checked_text(data.get('name'), 140)
        if name:
            result = org_get({'kind': data.get('kind'), 'name': name})
            if str(result['modified']) != str(data.get('expected_modified') or ''):
                fail('error.org_conflict')
            doc = frappe.get_doc(doctype, name)
            keys = ['short_name', 'company_name', 'tax_code', 'phone', 'email', 'address', 'active'] if doctype == 'Company' else ['department_name', 'company', 'active']
            code_key = 'company_code' if doctype == 'Company' else 'department_code'
            new_code = checked_text(data.get(code_key) or doc.get(code_key), 50, True)
            if new_code != doc.get(code_key):
                if doctype == 'Company':
                    org_company_scope(user, name)
                else:
                    org_company_scope(user, doc.company)
                name = org_rename(doctype, name, new_code)
                doc = frappe.get_doc(doctype, name)
            for key in keys:
                if key in data:
                    doc.set(key, data[key])
            doc.save(ignore_permissions=True)
        else:
            code_key = 'company_code' if doctype == 'Company' else 'department_code'
            code = checked_text(data.get(code_key), 50, True)
            if frappe.db.exists(doctype, code):
                fail('error.org_duplicate')
            values = {key: data.get(key) for key in (['short_name', 'company_name', 'tax_code', 'phone', 'email', 'address'] if doctype == 'Company' else ['department_name', 'company'])}
            doc = frappe.get_doc({'doctype': doctype, code_key: code, 'active': 1, **values})
            doc.insert(ignore_permissions=True)
        return org_values(doc)


    def org_deactivate(data):
        doc_data = org_get(data)
        if str(doc_data['modified']) != str(data.get('expected_modified') or ''):
            fail('error.org_conflict')
        doc = frappe.get_doc(org_kind(data), doc_data['name'])
        doc.active = 0
        doc.save(ignore_permissions=True)
        return org_values(doc)


    def read_rows(data):
        user = actor()
        start = check_date(data.get('from'))
        end = check_date(data.get('to'))
        if start and end and start > end:
            fail('error.filters')
        query = checked_text(data.get('query'), 100).lower()
        if data.get('status') and data.get('status') not in ['Draft', 'Pending Purchasing', 'Pending Approval', 'Approved', 'Closed', 'Returned', 'Rejected', 'Cancelled']:
            fail('error.filters')
        filters = {}
        for field in ['company', 'department', 'status']:
            if data.get(field):
                filters[field] = data.get(field)
        fields = ['name', 'company', 'department', 'requester', 'requester_name', 'purpose', 'status', 'priority', 'purchase_type', 'currency', 'request_date', 'required_date', 'final_total', 'estimated_total', 'priced_at', 'received_at', 'received_by', 'current_instance', 'modified', 'revision']
        rows = []
        for row in frappe.get_all(PR, filters=filters, fields=fields, limit_page_length=0):
            # Canonical permission runs before filtering, totals and pagination.
            if not can_read(user, row):
                continue
            date = str(row.get('request_date') or '')[:10]
            if (start and date < start) or (end and date > end):
                continue
            if query and not any(query in str(row.get(field) or '').lower() for field in ['name', 'purpose', 'requester_name']):
                continue
            rows.append(row)
        unpriced_names = [row.name for row in rows if not row.get('priced_at')]
        estimated_totals = {name: 0 for name in unpriced_names}
        if unpriced_names:
            items = frappe.get_all('PA Purchase Request Item',
                filters={'parent': ['in', unpriced_names]},
                fields=['parent', 'quantity', 'has_estimated_price', 'estimated_unit_price', 'estimated_vat_percent'],
                limit_page_length=0)
            for line in items:
                amounts = estimate_line_amounts(
                    line.get('quantity'), line.get('estimated_unit_price'),
                    line.get('estimated_vat_percent'), line.get('has_estimated_price'))
                estimated_totals[line.parent] = estimated_totals.get(line.parent, 0) + amounts['total']
        for row in rows:
            if row.get('priced_at'):
                row['amount'] = row.get('final_total') or 0
            else:
                row['estimated_total'] = estimated_totals.get(row.name, 0) / 100
                row['amount'] = row['estimated_total']
        return rows


    def read_history(rows):
        names = [row.name for row in rows]
        return frappe.get_all(HIST, filters={'request': ['in', names]}, fields=['name', 'request', 'creation', 'action', 'actor', 'actor_name', 'comment', 'step_order'], limit_page_length=0) if names else []


    def queue_matches(row, queue, history, user):
        if queue == 'all':
            return True
        if queue == 'mine':
            return row.requester == user
        if queue in ['approved_by_me', 'rejected_by_me']:
            action = 'Approve' if queue == 'approved_by_me' else 'Reject'
            return any(h.request == row.name and h.actor == user and h.action == action for h in history)
        if queue == 'received':
            return row.status == 'Closed' and row.received_by == user
        if queue == 'purchasing':
            return row.status == 'Pending Purchasing' and has_role(user, 'PA Purchasing')
        if queue == 'receiving':
            return row.status == 'Approved' and has_role(user, 'PA Receiver')
        if queue == 'approvals':
            if row.status != 'Pending Approval' or row.requester == user or not eligible(user, row) or not row.current_instance:
                return False
            instance = frappe.get_doc(INST, row.current_instance)
            return any(a.user == user and a.status == 'Pending' and a.step_order == instance.current_sequence for a in instance.assignees)
        fail('error.filters')


    def checked_queue(data, user):
        queue = data.get('queue') or 'all'
        capability = {'approvals': 'approvals', 'approved_by_me': 'approvals', 'rejected_by_me': 'approvals', 'purchasing': 'purchasing', 'receiving': 'receiving', 'received': 'receiving'}
        if queue not in ['all', 'mine'] and queue not in capability:
            fail('error.filters')
        if queue in capability and not read_capabilities(user)[capability[queue]]:
            fail('error.permission')
        return queue


    def list_requests(data):
        user = actor()
        try:
            page = max(0, min(int(data.get('page') or 0), 10000))
        except Exception:
            fail('error.required')
        queue = checked_queue(data, user)
        sort = data.get('sort') or 'modified'
        direction = data.get('direction') or 'desc'
        if sort not in ['modified', 'name', 'request_date', 'required_date', 'amount'] or direction not in ['asc', 'desc']:
            fail('error.filters')
        rows = read_rows(data)
        history = read_history(rows) if queue in ['approved_by_me', 'rejected_by_me'] else []
        visible = [row for row in rows if queue_matches(row, queue, history, user)]
        visible = sorted(visible, key=lambda row: (row.get(sort) or (0 if sort == 'amount' else ''), row.name), reverse=direction == 'desc')
        total = len(visible)
        return {'data': visible[page * 25:(page + 1) * 25], 'has_more': total > (page + 1) * 25, 'page': page, 'total': total, 'total_pages': (total + 24) // 25}


    def get_dashboard(data):
        user = actor()
        rows = read_rows(data)
        history = read_history(rows)
        capabilities = read_capabilities(user)
        metrics = {'mine': len([r for r in rows if r.requester == user]), 'returned_mine': len([r for r in rows if r.requester == user and r.status == 'Returned'])}
        for queue, capability in [('approvals', 'approvals'), ('approved_by_me', 'approvals'), ('rejected_by_me', 'approvals'), ('purchasing', 'purchasing'), ('receiving', 'receiving'), ('received', 'receiving')]:
            if capabilities[capability]:
                metrics[queue] = len([r for r in rows if queue_matches(r, queue, history, user)])
        totals = {}
        for row in rows:
            totals[row.company] = totals.get(row.company, 0) + row.amount
        recent = sorted(rows, key=lambda row: (str(row.modified or ''), row.name), reverse=True)[:10]
        activity = sorted(history, key=lambda row: (str(row.creation or ''), row.name), reverse=True)[:20]
        return {'metrics': metrics, 'recent': recent, 'activity': activity, 'company_totals': [{'company': company, 'company_name': frappe.db.get_value('Company', company, 'company_name') or company, 'amount': amount} for company, amount in sorted(totals.items())]}


    def workflow_options(data):
        user = actor()
        require_active_scope(user, data.get('company'), data.get('department'))
        request = frappe.get_doc({'doctype': PR, 'company': data.get('company'), 'department': data.get('department'), 'purchase_type': data.get('purchase_type') or 'Goods', 'currency': 'VND'})
        total = scaled(data.get('total')) if data.get('total') is not None else None
        return [{'name': w.name, 'workflow_name': w.workflow_name, 'amount_from': w.amount_from, 'has_amount_to': w.has_amount_to, 'amount_to': w.amount_to, 'specificity': (2 if w.department else 0) + (1 if w.purchase_type else 0), 'steps': [{'step_order': s.step_order, 'step_name': s.step_name, 'approval_method': s.approval_method, 'approver_source': s.approver_source} for s in w.steps]} for w in workflows_for(request, total)]


    def item_suggestions(data):
        user = actor()
        company = data.get('company')
        department = data.get('department')
        require_active_scope(user, company, department)
        if not read_capabilities(user)['create']:
            fail('error.permission')
        query = checked_text(data.get('query'), 100)
        if len(query) < 2:
            return []
        pattern = '%' + query + '%'
        is_super = super_user(user)
        shared = is_super or any(role in roles_of(user) for role in ['PA Manager', 'PA Purchasing', 'PA Approver', 'PA Receiver', 'PA Company Admin'])
        visibility = '' if is_super else " and (p.requester=%s or p.status!='Draft')" if shared else ' and p.requester=%s'
        params = [company, department, pattern, pattern]
        if not is_super:
            params.append(user)
        history = frappe.db.sql(
            "select i.item_code, i.item_name, i.description, i.uom, p.name as request_name, "
            "p.company, p.department, p.requester, p.status "
            "from `tabPA Purchase Request Item` i "
            "join `tabPA Purchase Request` p on p.name=i.parent "
            "where p.company=%s and p.department=%s "
            "and (i.item_name like %s or i.item_code like %s)" + visibility +
            ' order by p.modified desc, i.idx asc limit 500', tuple(params), as_dict=True)
        suggestions = []
        seen = set()
        visible_requests = {}
        for row in history:
            if row.request_name not in visible_requests:
                visible_requests[row.request_name] = can_read(user, row)
            if not visible_requests[row.request_name]:
                continue
            key = ((row.item_code or '').strip().casefold(), (row.item_name or '').strip().casefold())
            if not key[1] or key in seen:
                continue
            seen.add(key)
            suggestions.append({'name': '', 'product_code': row.item_code or '', 'product_name': row.item_name,
                                'description': row.description or '', 'uom': row.uom or '', 'source': 'history'})
            if len(suggestions) == 20:
                return suggestions
        products = frappe.db.sql(
            'select name, product_code, product_name from `tabProduct` '
            'where is_active=1 and (product_name like %s or product_code like %s) '
            'order by product_name limit 20', (pattern, pattern), as_dict=True)
        for row in products:
            key = ((row.product_code or '').strip().casefold(), (row.product_name or '').strip().casefold())
            if key in seen:
                continue
            seen.add(key)
            suggestions.append({'name': row.name, 'product_code': row.product_code or '',
                                'product_name': row.product_name, 'source': 'product'})
            if len(suggestions) == 20:
                break
        return suggestions


    def validate_workflow(doc):
        user = actor()
        require_role(user, 'PA Company Admin')
        require_scope(user, doc.company, doc.department)
        old = doc.get_doc_before_save()
        if old:
            require_scope(user, old.company, old.department)
        start = scaled(doc.amount_from)
        end = scaled(doc.amount_to)
        if doc.currency != 'VND' or (doc.has_amount_to and end <= start) or not doc.steps or len(doc.steps) > 30:
            fail('error.range')
        seen = []
        for step in doc.steps:
            if int(step.step_order or 0) < 1 or step.step_order in seen or step.approval_method not in ['Any', 'All'] or step.approver_source not in ['User', 'Role', 'Department Manager']:
                fail('error.range')
            seen.append(step.step_order)
            step.step_name = checked_text(step.step_name, 140, True)
            if step.approver_source == 'User' and not frappe.db.get_value('User', step.approver_user, 'enabled'):
                fail('error.no_approver')
            if step.approver_source == 'Role' and not frappe.db.exists('Role', step.approver_role):
                fail('error.no_approver')


    def workflow_admin_scope(user, company, department=None):
        require_role(user, 'PA Company Admin')
        require_scope(user, company, department)
        # A department-restricted admin cannot manage company-wide templates.
        if not department and not super_user(user) and frappe.get_all('User Permission', filters={'user': user, 'allow': 'Department'}, fields=['name'], limit_page_length=0):
            fail('error.permission')


    def workflow_admin_doc(name, lock=False):
        user = actor()
        require_role(user, 'PA Company Admin')
        name = checked_text(name, 140, True)
        row = frappe.db.get_value(WF, name, ['company', 'department'], as_dict=True)
        if not row:
            fail('error.not_found')
        try:
            workflow_admin_scope(user, row.company, row.department)
        except Exception:
            fail('error.not_found')
        doc = locked_doc(WF, name, lock)
        workflow_admin_scope(user, doc.company, doc.department)
        return doc


    def workflow_admin_result(doc):
        users = {}
        for step in doc.steps:
            if step.approver_source == 'User' and step.approver_user:
                users[step.approver_user] = frappe.db.get_value('User', step.approver_user, 'full_name') or step.approver_user
        return {'workflow': document_values(doc), 'labels': {'company': frappe.db.get_value('Company', doc.company, 'company_name') or doc.company, 'department': frappe.db.get_value('Department', doc.department, 'department_name') if doc.department else None, 'users': users}}


    def workflow_page(data):
        try:
            page = int(data.get('page') or 0)
            if page < 0 or page > 10000:
                fail('error.filters')
            return page
        except Exception:
            fail('error.filters')


    def list_approval_workflows(data):
        user = actor()
        require_role(user, 'PA Company Admin')
        page = workflow_page(data)
        query = checked_text(data.get('query'), 100).lower()
        active = data.get('active')
        if active not in [None, '', '0', '1', 0, 1]:
            fail('error.filters')
        if data.get('company'):
            require_scope(user, data.get('company'), data.get('department'))
        elif data.get('department'):
            fail('error.filters')
        filters = {key: data[key] for key in ['company', 'department'] if data.get(key)}
        if active not in [None, '']:
            filters['is_active'] = int(active)
        visible = []
        for row in frappe.get_all(WF, filters=filters, fields=['name', 'workflow_name', 'company', 'department', 'modified'], limit_page_length=0):
            try:
                workflow_admin_scope(user, row.company, row.department)
            except Exception:
                continue
            if not query or query in str(row.workflow_name or '').lower() or query in row.name.lower():
                visible.append(row)
        visible = sorted(visible, key=lambda row: (str(row.modified or ''), row.name), reverse=True)
        total = len(visible)
        return {'data': [workflow_admin_result(frappe.get_doc(WF, row.name)) for row in visible[page * 25:(page + 1) * 25]], 'page': page, 'total': total, 'total_pages': (total + 24) // 25, 'has_more': total > (page + 1) * 25}


    def workflow_assignee_options(company, department):
        workflow_admin_scope(actor(), company, department)
        target = frappe.get_doc({'doctype': PR, 'company': company, 'department': department})
        users = [row for row in frappe.get_all('User', filters={'enabled': 1}, fields=['name', 'full_name'], limit_page_length=0) if row.name != 'Guest' and eligible(row.name, target)]
        names = [row.name for row in users]
        role_names = []
        for row in frappe.get_all('Has Role', filters={'parenttype': 'User', 'parent': ['in', names]}, fields=['role'], limit_page_length=0) if names else []:
            if row.role not in role_names and frappe.db.exists('Role', {'name': row.role, 'disabled': 0}):
                role_names.append(row.role)
        return {'users': users, 'roles': sorted(role_names)}


    def workflow_assignees(data):
        options = workflow_assignee_options(data.get('company'), data.get('department'))
        users = options['users']
        roles = options['roles']
        query = checked_text(data.get('query'), 100).lower()
        page = workflow_page(data)
        visible = sorted([row for row in users if not query or query in row.name.lower() or query in str(row.full_name or '').lower()], key=lambda row: (str(row.full_name or '').lower(), row.name))
        return {'users': [{'name': row.name, 'full_name': row.full_name or row.name} for row in visible[page * 20:(page + 1) * 20]], 'roles': roles, 'page': page, 'has_more': len(visible) > (page + 1) * 20}


    def workflow_flag(value):
        if value not in [0, 1, '0', '1']:
            fail('error.required')
        return int(value)


    def save_approval_workflow(data):
        user = actor()
        require_role(user, 'PA Company Admin')
        company = checked_text(data.get('company'), 140, True)
        department = checked_text(data.get('department'), 140) or None
        workflow_admin_scope(user, company, department)
        options = workflow_assignee_options(company, department)
        users = options['users']
        roles = options['roles']
        user_names = [row.name for row in users]
        purchase_type = data.get('purchase_type') or ''
        if purchase_type not in ['', 'Goods', 'Service', 'Asset'] or data.get('currency', 'VND') != 'VND':
            fail('error.required')
        steps = data.get('steps')
        if not isinstance(steps, list) or not steps or len(steps) > 30:
            fail('error.range')
        normalized = []
        for index, step in enumerate(steps):
            if not isinstance(step, dict) or step.get('approval_method') not in ['Any', 'All'] or step.get('approver_source') not in ['User', 'Role', 'Department Manager']:
                fail('error.range')
            source = step['approver_source']
            assigned_user = checked_text(step.get('approver_user'), 140) if source == 'User' else ''
            assigned_role = checked_text(step.get('approver_role'), 140) if source == 'Role' else ''
            if (source == 'User' and assigned_user not in user_names) or (source == 'Role' and assigned_role not in roles):
                fail('error.workflow_assignee')
            normalized.append({'step_order': index + 1, 'step_name': checked_text(step.get('step_name'), 140, True), 'approval_method': step['approval_method'], 'approver_source': source, 'approver_user': assigned_user, 'approver_role': assigned_role})
        values = {'workflow_name': checked_text(data.get('workflow_name'), 140, True), 'company': company, 'department': department, 'purchase_type': purchase_type, 'currency': 'VND', 'amount_from': scaled(data.get('amount_from')) / 100, 'has_amount_to': workflow_flag(data.get('has_amount_to', 0)), 'amount_to': scaled(data.get('amount_to')) / 100 if data.get('has_amount_to') in [1, '1'] else 0, 'is_active': workflow_flag(data.get('is_active', 1)), 'note': checked_text(data.get('note'), 2000)}
        if values['has_amount_to'] and values['amount_to'] <= values['amount_from']:
            fail('error.range')
        if data.get('name'):
            doc = workflow_admin_doc(data['name'], True)
            if not data.get('expected_modified') or str(doc.modified) != str(data['expected_modified']):
                fail('error.conflict')
            for key in values:
                doc.set(key, values[key])
            doc.set('steps', normalized)
            doc.save(ignore_permissions=True)
        else:
            key = checked_text(data.get('idempotency_key'), 32, True).lower()
            if len(key) != 32 or any(c not in '0123456789abcdef' for c in key):
                fail('error.idempotency')
            name = 'PAWF-' + key
            query_lock('select name from `tabCompany` where name=%s for update', (company,))
            if frappe.db.exists(WF, name):
                existing = workflow_admin_doc(name, True)
                same_steps = [{field: step.get(field) or '' for field in ['step_name', 'approval_method', 'approver_source', 'approver_user', 'approver_role']} for step in existing.steps]
                requested_steps = [{field: step.get(field) or '' for field in ['step_name', 'approval_method', 'approver_source', 'approver_user', 'approver_role']} for step in normalized]
                if existing.owner != user or any((existing.get(field) or '') != (values[field] or '') for field in values) or same_steps != requested_steps:
                    fail('error.idempotency')
                return workflow_admin_result(existing)
            doc = frappe.get_doc({'doctype': WF, **values, 'steps': normalized})
            doc.insert(ignore_permissions=True, set_name=name)
        return workflow_admin_result(doc)


    def validate_supplier(doc):
        require_role(actor(), 'PA Company Admin')
        if not doc.companies:
            fail('error.required')
        old = doc.get_doc_before_save()
        if old:
            for row in old.companies:
                require_scope(actor(), row.company)
        for row in doc.companies:
            require_scope(actor(), row.company)


    def cancel_notifications(instance_name):
        for row in frappe.get_all('PA Notification Outbox', filters={'instance': instance_name, 'status': 'Pending'}, fields=['name']):
            frappe.db.set_value('PA Notification Outbox', row.name, 'status', 'Cancelled')


    def notify_step(request, instance):
        for row in instance.assignees:
            if row.step_order == instance.current_sequence and row.status == 'Pending':
                key = instance.name + ':' + str(row.step_order) + ':' + row.user
                existing = frappe.db.get_value('PA Notification Outbox', {'notification_key': key}, ['name', 'status'], as_dict=True)
                if existing:
                    if existing.status == 'Cancelled':
                        frappe.db.set_value('PA Notification Outbox', existing.name, 'status', 'Pending')
                    continue
                outbox = frappe.get_doc({'doctype': 'PA Notification Outbox', 'request': request.name, 'instance': instance.name, 'step_order': row.step_order, 'recipient': row.user, 'notification_key': key, 'subject': t('notification.subject') + ' ' + request.name, 'body': t('notification.body'), 'status': 'Pending'})
                outbox.insert(ignore_permissions=True)


    def notification_worker():
        if not frappe.db.get_single_value('PA Settings', 'email_enabled'):
            return
        for row in frappe.get_all('PA Notification Outbox', filters={'status': 'Pending', 'attempts': ['<', 5]}, fields=['name'], limit_page_length=100):
            query_lock('select name from `tabPA Notification Outbox` where name=%s for update', (row.name,))
            outbox = locked_doc('PA Notification Outbox', row.name)
            if outbox.status != 'Pending':
                continue
            instance = frappe.get_doc(INST, outbox.instance)
            request = frappe.get_doc(PR, outbox.request)
            active = request.status == 'Pending Approval' and instance.status == 'Pending' and request.current_instance == instance.name and instance.current_sequence == outbox.step_order and eligible(outbox.recipient, request) and any(a.user == outbox.recipient and a.step_order == outbox.step_order and a.status == 'Pending' for a in instance.assignees)
            if not active:
                outbox.status = 'Cancelled'
            else:
                outbox.attempts = int(outbox.attempts or 0) + 1
                try:
                    url = frappe.utils.get_url('/purchase-approval?request=' + request.name)
                    frappe.sendmail(recipients=[outbox.recipient], subject=outbox.subject, message=frappe.utils.escape_html(outbox.body) + '<br><a href="' + frappe.utils.escape_html(url) + '">' + frappe.utils.escape_html(request.name) + '</a>')
                    outbox.status = 'Sent'
                    outbox.sent_at = frappe.utils.now()
                    outbox.last_error = None
                except Exception:
                    outbox.last_error = t('error.email')
            outbox.save(ignore_permissions=True)


    def dispatch(command):
        user = actor()
        if not super_user(user) and not any(role in roles_of(user) for role in ['PA Requester', 'PA Manager', 'PA Purchasing', 'PA Approver', 'PA Receiver', 'PA Company Admin']):
            fail('error.permission')
        raw = frappe.form_dict.get('payload') or '{}'
        try:
            parsed = json.loads(raw) if isinstance(raw, str) else raw
            if not isinstance(parsed, dict):
                fail('error.required')
            data = dict(parsed)
        except Exception:
            fail('error.required')
        if command == 'create_purchase_request':
            return create_request(data)
        if command == 'save_purchase_request':
            return save_request(data)
        if command == 'submit_purchase_request':
            return submit_request(data)
        if command == 'finalize_purchase_request':
            return finalize_request(data)
        if command == 'approval_action':
            return approval_action(data)
        if command == 'receive_purchase_request':
            return receive_request(data)
        if command == 'cancel_purchase_request':
            return cancel_request(data)
        if command == 'reassign_approver':
            return reassign(data)
        if command == 'get_context':
            return get_context(data)
        if command == 'get_purchase_request':
            return request_details(lock_request(data.get('name'), {}, False))
        if command == 'list_purchase_requests':
            return list_requests(data)
        if command == 'get_dashboard':
            return get_dashboard(data)
        if command == 'workflow_options':
            return workflow_options(data)
        if command == 'item_suggestions':
            return item_suggestions(data)
        if command == 'list_approval_workflows':
            return list_approval_workflows(data)
        if command == 'get_approval_workflow':
            return workflow_admin_result(workflow_admin_doc(data.get('name')))
        if command == 'workflow_assignees':
            return workflow_assignees(data)
        if command == 'save_approval_workflow':
            return save_approval_workflow(data)
        if command == 'list_organizations':
            return org_list(data)
        if command == 'get_organization':
            return org_get(data)
        if command == 'save_organization':
            return org_save(data)
        if command == 'deactivate_organization':
            return org_deactivate(data)
        fail('error.status')

    validate_workflow(doc)

pa_execute(doc)

