frappe.ui.form.on('PA Approval Workflow', {
  async setup(frm){
    const ctx=await PA.boot();
    frm.set_df_property('purchase_type','options',['',...['Goods','Service','Asset'].map(value=>PA.option(value,PA.t('type.'+value)))]);
    frm.fields_dict.steps.grid.update_docfield_property('approval_method','options',['Any','All'].map(value=>PA.option(value,PA.t('mode.'+value))));
    frm.fields_dict.steps.grid.update_docfield_property('approver_source','options',['User','Role','Department Manager'].map(value=>PA.option(value,PA.t('source.'+value))));
    frm.set_query('company',()=>({filters:{name:['in',ctx.companies.map(c=>c.name)]}}));
    frm.set_query('department',()=>({filters:{name:['in',ctx.departments.filter(d=>d.company===frm.doc.company).map(d=>d.name)]}}));
  },
  company(frm){frm.set_value('department','');},
  has_amount_to(frm){frm.toggle_display('amount_to',!!frm.doc.has_amount_to);},
  refresh(frm){frm.toggle_display('amount_to',!!frm.doc.has_amount_to);}
});

