ice-history-entry[open]>summary{border-bottom:1px solid var(--pa-line);background:var(--pa-bg)}\n:where(.pa-root,.pa-request-price-lines-field) .pa-price-history-meta{padding:8px 12px;color:var(--pa-muted)}\n.pa-request-price-lines-field .pa-price-history-section>h3{margin:24px 0 8px}\n";document.head.append(s);}
const renderPriceLines=(frm,request,priceHistory)=>{
    const field=frm.fields_dict.pa_request_price_lines_html;
    const wrapper=field?.$wrapper?.find('.control-input-wrapper')?.get(0)||field?.$wrapper?.get(0);
    if(!wrapper)return;
    wrapper.classList.add('pa-request-price-lines-field');
    const priced=Boolean(request.priced_at),items=request.items||[];
    const columns=priced
      ?['common.line_number','field.item_name','field.uom','field.quantity','field.final_unit_price_net','field.vat_percent','field.final_tax','field.final_amount']
      :['common.line_number','field.item_name','field.uom','field.quantity','field.estimated_unit_price','field.estimated_vat_percent','field.estimated_gross_amount'];
    const rows=items.map((line,index)=>{
      const item=PA.node('div'),description=[line.item_code,line.description,line.note].filter(Boolean).join(' · ');
      item.append(PA.node('strong',line.item_name));
      if(description)item.append(PA.node('div',description,{class:'pa-price-line-detail'}));
      if(priced)return[index+1,item,line.uom,PA.money(line.quantity),PA.money(line.final_unit_price_net),PA.money(line.vat_percent)+'%',PA.money(line.final_tax),PA.money(line.final_amount)];
      const estimated=Number(line.has_estimated_price)===1;
      return[index+1,item,line.uom,PA.money(line.quantity),estimated?PA.money(line.estimated_unit_price):PA.t('common.unavailable'),PA.money(line.estimated_vat_percent)+'%',estimated?PA.money(line.estimated_amount):PA.t('common.unavailable')];
    });
    const table=PA.table(columns,rows),tableElement=table.querySelector('.pa-table');
    tableElement?.classList.add('pa-price-lines-table',priced?'pa-price-lines-priced':'pa-price-lines-estimate');
    const summary=PA.node('div',null,{class:'pa-price-lines-summary'});
    const addSummary=(key,value,grand=false)=>{const row=PA.node('div',null,{class:'pa-price-lines-summary-row'+(grand?' pa-grand-total':'')});row.append(PA.node('span',PA.t(key)),PA.node('strong',value));summary.append(row);};
    if(priced){
      addSummary('field.final_subtotal',PA.money(request.final_subtotal)+' '+request.currency);
      addSummary('field.final_tax',PA.money(request.final_tax)+' '+request.currency);
      addSummary('field.final_total',PA.money(request.final_total)+' '+request.currency,true);
    }else{
      const subtotal=items.reduce((total,line)=>Number(line.has_estimated_price)===1?total+Number(line.quantity||0)*Number(line.estimated_unit_price||0):total,0);
      const estimatedTotal=Number(request.estimated_total)||items.reduce((total,line)=>total+Number(line.estimated_amount||0),0);
      addSummary('field.estimated_subtotal',PA.money(subtotal)+' '+request.currency);
      addSummary('field.estimated_tax',PA.money(Math.max(0,estimatedTotal-subtotal))+' '+request.currency);
      addSummary('field.estimated_gross_total',PA.money(estimatedTotal)+' '+request.currency,true);
    }
    let mount=wrapper.querySelector('.pa-request-price-lines-content');
    if(!mount){mount=PA.node('div',null,{class:'pa-request-price-lines-content'});wrapper.append(mount);}
    const history=PA.node('section',null,{class:'pa-price-history-section'});
    history.append(PA.node('h3',PA.t('common.price_history')),PA.priceHistory(priceHistory));
    mount.replaceChildren(table,summary,history);
};

frappe.ui.form.on('PA Purchase Request', {
  async refresh(frm) {
    await PA.boot();
    for(const [field,key] of Object.entries({pa_request_info_section:'common.request_document',pa_request_financial_section:'common.price_lines',pa_request_approval_section:'common.approval_steps'})){
      if(!frm.fields_dict[field])continue;
      frm.set_df_property(field,'label',PA.t(key));
      frm.refresh_field(field);
    }
    for(const field of ['estimated_total','final_subtotal','final_tax','final_total']){
      frm.set_df_property(field,'hidden',1);
      frm.refresh_field(field);
    }
    frm.set_df_property('purchase_type','options',['Goods','Service','Asset'].map(value=>PA.option(value,PA.t('type.'+value))));
    frm.set_df_property('priority','options',['Low','Normal','High','Urgent'].map(value=>PA.option(value,PA.t('priority.'+value))));
    frm.set_df_property('status','options',['Draft','Pending Purchasing','Pending Approval','Approved','Closed','Returned','Rejected','Cancelled'].map(value=>PA.option(value,PA.t('status.'+value))));
    frm.disable_save();
    frm.clear_custom_buttons();
    if(frm.is_new()){
      const key=frm.pa_key ||= PA.idempotencyKey();
      frm.add_custom_button(PA.t('action.save'),async()=>{
        const result=await PA.call('create_purchase_request',{...frm.doc,idempotency_key:key});
        frappe.set_route('Form','PA Purchase Request',result.request.name);
      });return;
    }
    const detail=await PA.call('get_purchase_request',{name:frm.doc.name});frm.pa_detail=detail;renderPriceLines(frm,detail.request,detail.price_history);
    for(const action of detail.actions)frm.add_custom_button(PA.t('action.'+action),async()=>{
      const next=action==='save'?await PA.call('save_purchase_request',{...frm.doc,...PA.expected(detail.request)}):await PA.act(action,detail);
      if(next)await frm.reload_doc();
    });
    for(const field of ['company','department','request_date','required_date','purchase_type','priority','purpose','project','note','items','selected_workflow'])frm.set_df_property(field,'read_only',detail.actions.includes('save')?0:1);
    frm.set_df_property('company','read_only',1);frm.set_df_property('department','read_only',1);
  },
  async setup(frm){
    const ctx=await PA.boot();
    frm.set_query('company',()=>({filters:{name:['in',ctx.companies.map(c=>c.name)]}}));
    frm.set_query('department',()=>({filters:{name:['in',ctx.departments.filter(d=>d.company===frm.doc.company).map(d=>d.name)]}}));
  }
});

