{% set unavailable = 'Không có dữ liệu' %}
{% set status_labels = {
  'Draft': 'Nháp',
  'Pending Purchasing': 'Chờ mua hàng định giá',
  'Pending Approval': 'Chờ phê duyệt',
  'Approved': 'Đã duyệt',
  'Closed': 'Đã nhận hàng',
  'Returned': 'Trả sửa',
  'Rejected': 'Từ chối',
  'Cancelled': 'Đã hủy'
} %}
{% set purchase_type_labels = {
  'Goods': 'Hàng hóa',
  'Service': 'Dịch vụ',
  'Asset': 'Tài sản'
} %}
{% set logo = namespace(field='') %}
{% for field in frappe.get_meta('KTG Company').fields %}
  {% if not logo.field and ('logo' in (field.fieldname or '').lower() or 'logo' in (field.label or '').lower()) %}
    {% set logo.field = field.fieldname %}
  {% endif %}
{% endfor %}
{% if not logo.field %}
  {% for field in frappe.get_meta('KTG Company').fields %}
    {% if not logo.field and ('image' in (field.fieldname or '').lower() or 'image' in (field.label or '').lower()) %}
      {% set logo.field = field.fieldname %}
    {% endif %}
  {% endfor %}
{% endif %}
{% set company_logo = frappe.db.get_value('KTG Company', doc.company, logo.field) if logo.field else none %}
{% if not company_logo %}{% set company_logo = frappe.db.get_single_value('Website Settings', 'app_logo') %}{% endif %}
{% set company_name = frappe.db.get_value('KTG Company', doc.company, 'company_name') or doc.company %}
{% set department_name = frappe.db.get_value('KTG Department', doc.department, 'department_name') or doc.department %}
{% set requester_name = doc.requester_name or frappe.db.get_value('User', doc.requester, 'full_name') or doc.requester %}
{% set supplier_name = frappe.db.get_value('PA Supplier', doc.supplier, 'supplier_name') if doc.supplier else '' %}
{% set priced = 1 if doc.priced_at else 0 %}

<main class="pa-request-invoice">
  <header class="pa-invoice-header">
    <div class="pa-invoice-logo">
      {% if company_logo %}<img src="{{ frappe.utils.get_url(company_logo) }}" alt="" />{% endif %}
    </div>
    <h1>ĐỀ NGHỊ MUA HÀNG</h1>
    <div class="pa-invoice-meta">
      <strong>{{ doc.name | e }}</strong>
      <span>{{ frappe.utils.formatdate(doc.request_date) if doc.request_date else unavailable }}</span>
      <span class="pa-invoice-status">{{ status_labels.get(doc.status, doc.status) | e }}</span>
    </div>
  </header>

  <section class="pa-request-info">
    <div><label>Công ty</label><span>{{ company_name | e }}</span></div>
    <div><label>Phòng ban</label><span>{{ department_name | e }}</span></div>
    <div><label>Tên người đề nghị</label><span>{{ requester_name | e }}</span></div>
    <div><label>Ngày cần hàng</label><span>{{ frappe.utils.formatdate(doc.required_date) if doc.required_date else unavailable }}</span></div>
    <div><label>Loại mua</label><span>{{ purchase_type_labels.get(doc.purchase_type, doc.purchase_type) | e }}</span></div>
    <div><label>Nhà cung cấp</label><span>{{ supplier_name | e if supplier_name else unavailable }}</span></div>
    {% if doc.project %}<div><label>Dự án</label><span>{{ doc.project | e }}</span></div>{% endif %}
    <div class="pa-request-full"><label>Mục đích đề nghị</label><span>{{ doc.purpose | e if doc.purpose else unavailable }}</span></div>
    <div class="pa-request-full"><label>Ghi chú</label><span>{{ doc.note | e if doc.note else unavailable }}</span></div>
  </section>

  <table class="pa-invoice-lines">
    <thead>
      <tr>
        <th>STT</th>
        <th>Tên hàng</th>
        <th>Đơn vị tính</th>
        <th class="pa-number">Số lượng</th>
        {% if priced %}
          <th class="pa-number">Đơn giá mua trước VAT</th>
          <th class="pa-number">VAT (%)</th>
          <th class="pa-number">Tiền thuế</th>
          <th class="pa-number">Thành tiền sau thuế</th>
        {% else %}
          <th class="pa-number">Đơn giá ước tính</th>
          <th class="pa-number">VAT ước tính (%)</th>
          <th class="pa-number">Thành tiền ước tính</th>
        {% endif %}
      </tr>
    </thead>
    <tbody>
      {% for item in doc.items %}
        <tr>
          <td class="pa-center">{{ loop.index }}</td>
          <td>
            <strong>{{ item.item_name | e }}</strong>
            {% set details = [item.item_code, item.description, item.note, frappe.utils.formatdate(item.delivery_date) if item.delivery_date else ''] | select | list %}
            {% if details %}<div class="pa-line-details">{{ details | join(' · ') | e }}</div>{% endif %}
          </td>
          <td>{{ item.uom | e }}</td>
          <td class="pa-number">{{ frappe.format_value(item.quantity, {'fieldtype':'Float','precision':4}) }}</td>
          {% if priced %}
            <td class="pa-number">{{ frappe.utils.fmt_money(item.final_unit_price_net, precision=0) }}</td>
            <td class="pa-number">{{ frappe.utils.fmt_money(item.vat_percent or 0, precision=2) }}%</td>
            <td class="pa-number">{{ frappe.utils.fmt_money(item.final_tax, precision=0) }}</td>
            <td class="pa-number">{{ frappe.utils.fmt_money(item.final_amount, precision=0) }}</td>
          {% else %}
            {% if item.has_estimated_price | int %}
              <td class="pa-number">{{ frappe.utils.fmt_money(item.estimated_unit_price, precision=0) }}</td>
              <td class="pa-number">{{ frappe.utils.fmt_money(item.estimated_vat_percent or 0, precision=2) }}%</td>
              <td class="pa-number">{{ frappe.utils.fmt_money(item.estimated_amount, precision=0) }}</td>
            {% else %}
              <td class="pa-number">{{ unavailable }}</td>
              <td class="pa-number">{{ frappe.utils.fmt_money(item.estimated_vat_percent or 0, precision=2) }}%</td>
              <td class="pa-number">{{ unavailable }}</td>
            {% endif %}
          {% endif %}
        </tr>
      {% endfor %}
    </tbody>
  </table>

  <section class="pa-invoice-totals">
    {% if priced %}
      <div><span>Tổng trước thuế</span><strong>{{ frappe.utils.fmt_money(doc.final_subtotal, precision=0, currency=doc.currency) }}</strong></div>
      <div><span>Tiền thuế</span><strong>{{ frappe.utils.fmt_money(doc.final_tax, precision=0, currency=doc.currency) }}</strong></div>
      <div class="pa-invoice-grand-total"><span>Tổng sau thuế</span><strong>{{ frappe.utils.fmt_money(doc.final_total, precision=0, currency=doc.currency) }}</strong></div>
    {% else %}
      <div class="pa-invoice-grand-total"><span>Tổng ước tính</span><strong>{{ frappe.utils.fmt_money(doc.estimated_total, precision=0, currency=doc.currency) }}</strong></div>
    {% endif %}
  </section>
</main>

print_formats.css:
@page {
  size: A4 landscape;
  margin: 12mm;
}

* {
  box-sizing: border-box;
}

body {
  color: #151515;
  font-family: Arial, "DejaVu Sans", sans-serif;
  font-size: 9pt;
}

.pa-request-invoice {
  width: 100%;
}

.pa-invoice-header {
  display: grid;
  grid-template-columns: 1fr 2fr 1fr;
  align-items: center;
  gap: 14px;
  padding-bottom: 14px;
  margin-bottom: 18px;
  border-bottom: 2px solid #222;
}

.pa-invoice-logo img {
  display: block;
  max-width: 145px;
  max-height: 52px;
  object-fit: contain;
}

.pa-invoice-header h1 {
  margin: 0;
  text-align: center;
  font-size: 16pt;
}

.pa-invoice-meta {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 5px;
  text-align: right;
}

.pa-invoice-meta strong {
  overflow-wrap: anywhere;
}

.pa-invoice-status {
  padding: 3px 9px;
  border: 1px solid #777;
  border-radius: 5px;
}

.pa-request-info {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0 20px;
  margin-bottom: 22px;
}

.pa-request-info > div {
  display: grid;
  gap: 4px;
  padding: 6px 0;
  border-bottom: 1px solid #bbb;
  break-inside: avoid;
}

.pa-request-info label {
  color: #555;
}

.pa-request-info span {
  font-weight: 500;
  overflow-wrap: anywhere;
}

.pa-request-full {
  grid-column: 1 / -1;
}

.pa-invoice-lines {
  width: 100%;
  table-layout: fixed;
  border: 1px solid #333;
  border-collapse: collapse;
  font-size: 7.5pt;
}

.pa-invoice-lines th,
.pa-invoice-lines td {
  padding: 5px 5px;
  border: 1px solid #999;
  vertical-align: top;
  overflow-wrap: anywhere;
}

.pa-invoice-lines th {
  background: #f0f0f0;
  border-top: 1px solid #333;
  border-bottom: 1px solid #333;
  text-align: left;
}

.pa-invoice-lines tr {
  break-inside: avoid;
}

.pa-invoice-lines th:first-child,
.pa-invoice-lines td:first-child {
  width: 4%;
  text-align: center;
}

.pa-invoice-lines th:nth-child(2),
.pa-invoice-lines td:nth-child(2) {
  width: 30%;
}

.pa-invoice-lines .pa-number {
  text-align: right;
  font-variant-numeric: tabular-nums;
}

.pa-invoice-lines td.pa-number {
  white-space: nowrap;
  overflow-wrap: normal;
  word-break: keep-all;
}

.pa-invoice-lines .pa-center {
  text-align: center;
}

.pa-line-details {
  margin-top: 3px;
  color: #555;
  line-height: 1.35;
}

.pa-invoice-totals {
  width: min(46%, 440px);
  margin: 18px 0 0 auto;
  border-top: 1px solid #555;
}

.pa-invoice-totals > div {
  display: flex;
  justify-content: space-between;
  gap: 20px;
  padding: 8px 0;
  border-bottom: 1px solid #bbb;
}

.pa-invoice-totals strong {
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
}

.pa-invoice-totals .pa-invoice-grand-total {
  border-top: 1px solid #444;
  border-bottom: 1px solid #444;
  font-size: 10pt;
  font-weight: 700;
}
